// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ANCHToken} from "../src/ANCHToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ANCHToken c;

    function setUp() public {
        vm.prank(0x000000000000000000000000000000000000bEEF, 0x000000000000000000000000000000000000bEEF);
        c = new ANCHToken(address(this), address(this));
    }

    function _run(address originalOwnerCandidate, address newOwner) internal {
        address orig;
        try c.owner() returns (address __r) { orig = __r; } catch { return; }
        vm.assume(orig == originalOwnerCandidate);
        try c.changeOwner(newOwner) {} catch { return; }
        assertTrue(!(address(this) != orig) || (c.owner() == orig));
    }

    function testFuzz_run(address originalOwnerCandidate, address newOwner) public {
        _run(originalOwnerCandidate, newOwner);
    }

    receive() external payable {}
    function factory() external view returns (address) { return address(this); }
    function createPair(address, address) external pure returns (address) { return address(1); }

}
